// All of these expose an OpenAI-compatible POST {base}/chat/completions
const PROVIDERS = {
  openai:     { url: 'https://api.openai.com/v1',                              model: 'gpt-4.1-mini',            key: cfg.openai_api_key },
  gemini:     { url: 'https://generativelanguage.googleapis.com/v1beta/openai', model: 'gemini-2.5-flash',        key: cfg.gemini_api_key },
  grok:       { url: 'https://api.x.ai/v1',                                    model: 'grok-4',                  key: cfg.xai_api_key },
  groq:       { url: 'https://api.groq.com/openai/v1',                         model: 'llama-3.3-70b-versatile', key: cfg.groq_api_key },
  mistral:    { url: 'https://api.mistral.ai/v1',                              model: 'mistral-large-latest',    key: cfg.mistral_api_key },
  deepseek:   { url: 'https://api.deepseek.com/v1',                            model: 'deepseek-chat',           key: cfg.deepseek_api_key },
  openrouter: { url: 'https://openrouter.ai/api/v1',                           model: 'openai/gpt-4.1-mini',     key: cfg.openrouter_api_key },
  ollama:     { url: 'http://localhost:11434/v1',                              model: 'llama3.1:8b',             key: 'ollama' },
  custom:     { url: String(cfg.custom_base_url || '').replace(/\/+$/, ''),    model: '',                        key: cfg.custom_api_key }
};
const ALIAS = { xai: 'grok', 'x.ai': 'grok', google: 'gemini', 'google-gemini': 'gemini', chatgpt: 'openai' };

let provider = String(cfg.provider || cfg.default_provider || 'openai').toLowerCase().trim();
provider = ALIAS[provider] || provider;
const p = PROVIDERS[provider];
if (!p) throw new Error('Unknown provider "' + provider + '". Use one of: ' + Object.keys(PROVIDERS).join(', '));

const model = String(cfg.model || cfg.default_model || p.model || '').trim();
if (!model) throw new Error('No model set for provider "' + provider + '". Fill default_model in the Config node.');
if (!p.url) throw new Error('No base URL for provider "' + provider + '". Fill custom_base_url in the Config node.');
const key = String(p.key || '').trim();
if (!key) throw new Error('No API key for provider "' + provider + '". Paste it into the matching *_api_key field in the Config node.');

// OpenAI reasoning models (o-series, gpt-5*) reject a custom temperature -> omit it for them
const sendTemperature = !/^(o\d|gpt-5)/i.test(model);

const out = { ...cfg, provider, model, llm_base_url: p.url, llm_api_key: key, send_temperature: sendTemperature };
['openai_api_key','gemini_api_key','xai_api_key','groq_api_key','mistral_api_key','deepseek_api_key','openrouter_api_key','custom_api_key','default_model','default_provider','custom_base_url'].forEach(k => delete out[k]);
return [{ json: out }];
